```typescript
import { POST } from './route';
import { NextRequest } from 'next/server';

describe('POST /api/test-webhook', () => {
  it('rejects invalid URL', async () => {
    const req = new NextRequest(new URL('http://localhost/api/test-webhook'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ targetUrl: 'not-a-url' }),
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('rejects javascript: protocol', async () => {
    const req = new NextRequest(new URL('http://localhost/api/test-webhook'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ targetUrl: 'javascript:alert(1)' }),
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it('returns 400 on missing payload schema', async () => {
    const req = new NextRequest(new URL('http://localhost/api/test-webhook'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    const res = await POST(req);
    // targetUrl is required by schema
    expect(res.status).toBe(400);
  });
});
```

**Security Decisions:**
1.  **Server-Side Proxy:** The request is fetched on the server, not the client, preventing client-side CORS issues and exposing secrets (if any were in headers) to the user's browser.
2.  **Schema Validation:** Uses `zod` to enforce `targetUrl` is a valid URL string and `payload` is an object.
3.  **Protocol Allowlist:** Explicitly checks `http:` or `https:` to block `javascript:`, `data:`, etc.
4.  **Timeout:** `AbortSignal.timeout(3000)` prevents slow-loris attacks or hanging connections.
5.  **Structured Logging:** Errors are logged on the server; the response returns a generic message to the client.
